   394→        chain.seenGossipBlockInput.prune();
   395→      })
   396→      .catch((e) => {
   397→        // Adjust verbosity based on error type
   398→        let logLevel: LogLevel;
   399→
   400→        if (e instanceof BlockError) {
   401→          switch (e.type.code) {
   402→            case BlockErrorCode.DATA_UNAVAILABLE: {
