   412→            }
   413→            // ALREADY_KNOWN should not happen with ignoreIfKnown=true above
   414→            // PARENT_UNKNOWN should not happen, we handled this in validateBeaconBlock() function above
   415→            case BlockErrorCode.ALREADY_KNOWN:
   416→            case BlockErrorCode.PARENT_UNKNOWN:
   417→            case BlockErrorCode.PRESTATE_MISSING:
   418→            case BlockErrorCode.EXECUTION_ENGINE_ERROR:
   419→              // Errors might indicate an issue with our node or the connected EL client
   420→              logLevel = LogLevel.error;
   421→              break;
   422→            default:
   423→              // TODO: Should it use PeerId or string?
   424→              core.reportPeer(peerIdStr, PeerAction.LowToleranceError, "BadGossipBlock");
   425→              // Misbehaving peer, but could highlight an issue in another client
   426→              logLevel = LogLevel.warn;
   427→          }
   428→        } else {
   429→          // Any unexpected error
   430→          logLevel = LogLevel.error;
   431→        }
   432→        metrics?.gossipBlock.processBlockErrors.inc({error: e instanceof BlockError ? e.type.code : "NOT_BLOCK_ERROR"});
   433→        logger[logLevel]("Error receiving block", {slot: signedBlock.message.slot, peer: peerIdStr}, e as Error);
   434→        chain.seenGossipBlockInput.prune();
   435→      });
   436→
   437→    if (blockInput.type === BlockInputType.dataPromise) {
   438→      const blockSlot = blockInput.block.message.slot;
   439→      // if blobs are not yet fully available start an aggressive blob pull
   440→      chain.logger.debug("Block under processing is not available, racing with cutoff to add to unknownBlockInput", {
   441→        blockSlot,
   442→      });
   443→      raceWithCutoff(
   444→        chain,
   445→        blockSlot,
   446→        blockInput.cachedData.availabilityPromise as Promise<BlockInputAvailableData>,
